/** Drop whole month partitions instead of deleting rows (Phase 18.T10). */
import { quoteIdent } from '../storage.js';
import type { Database } from '../types.js';

export interface DroppedPartition {
  parent: string;
  partition: string;
  rows: number;
}

/** Month keys are generated by the migrations; anything else is ignored. */
function monthKey(date: Date): string {
  return `${date.getUTCFullYear()}_${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
}

function monthStart(date: Date, offsetMonths: number): Date {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + offsetMonths, 1));
}

/**
 * Create a month partition window. Retention calls this before/after dropping
 * so a long-running install never falls back to the default partition for
 * future writes, and backdated writes get a short late-arrival window.
 * Idempotent.
 */
export async function ensureMonthPartitions(
  database: Database,
  parent: string,
  now = new Date(),
  aheadMonths = 2,
  behindMonths = 0,
  keyColumn = 'created_at',
): Promise<string[]> {
  const created: string[] = [];
  const parentIdent = quoteIdent(parent);
  const keyIdent = quoteIdent(keyColumn);
  const defaultName = `${parent}_default`;
  for (let offset = -behindMonths; offset <= aheadMonths; offset += 1) {
    const start = monthStart(now, offset);
    const end = monthStart(now, offset + 1);
    const name = `${parent}_${monthKey(start)}`;
    const existing = await database.query(`SELECT 1 FROM pg_class WHERE relname = $1`, [name]);
    if (existing.length > 0) continue;
    // A backdated/future row may already sit in the default partition; it must
    // be moved before PostgreSQL can attach a partition covering its range.
    const hasDefault = await database.query(`SELECT 1 FROM pg_class WHERE relname = $1`, [
      defaultName,
    ]);
    if (hasDefault.length > 0) {
      const staged = `${name}_move`;
      await database.query(
        `CREATE TEMP TABLE ${quoteIdent(staged)} AS
         WITH moved AS (
           DELETE FROM ${quoteIdent(defaultName)}
            WHERE ${keyIdent} >= $1 AND ${keyIdent} < $2
           RETURNING *
         )
         SELECT * FROM moved`,
        [start, end],
      );
      await database.query(
        `CREATE TABLE ${quoteIdent(name)} PARTITION OF ${parentIdent}
         FOR VALUES FROM ('${start.toISOString()}') TO ('${end.toISOString()}')`,
      );
      await database.query(`INSERT INTO ${parentIdent} SELECT * FROM ${quoteIdent(staged)}`);
      await database.query(`DROP TABLE ${quoteIdent(staged)}`);
    } else {
      await database.query(
        `CREATE TABLE ${quoteIdent(name)} PARTITION OF ${parentIdent}
         FOR VALUES FROM ('${start.toISOString()}') TO ('${end.toISOString()}')`,
      );
    }
    created.push(name);
  }
  const hasDefault = await database.query(`SELECT 1 FROM pg_class WHERE relname = $1`, [
    defaultName,
  ]);
  if (hasDefault.length === 0) {
    await database.query(
      `CREATE TABLE ${quoteIdent(defaultName)} PARTITION OF ${parentIdent} DEFAULT`,
    );
    created.push(defaultName);
  }
  return created;
}

/**
 * Drop child partitions whose `_YYYY_MM` suffix is before `before`. The row
 * count is read before the drop so the retention report can keep the row-based
 * `deleted` shape callers already expect.
 */
export async function dropExpiredPartitions(
  database: Database,
  parent: string,
  before: Date,
): Promise<DroppedPartition[]> {
  const rows = await database.query<{ relname: string }>(
    `SELECT child.relname
     FROM pg_inherits
     JOIN pg_class parent ON parent.oid = pg_inherits.inhparent
     JOIN pg_class child ON child.oid = pg_inherits.inhrelid
     WHERE parent.relname = $1`,
    [parent],
  );
  const cutoff = monthKey(before);
  const dropped: DroppedPartition[] = [];
  for (const row of rows) {
    const suffix = /_(\d{4}_\d{2})$/.exec(row.relname)?.[1];
    if (!suffix || suffix >= cutoff) continue;
    const counted = await database.query<{ count: number }>(
      `SELECT COUNT(*)::int AS count FROM "${row.relname.replace(/"/g, '""')}"`,
    );
    await database.query(`DROP TABLE IF EXISTS "${row.relname.replace(/"/g, '""')}"`);
    dropped.push({ parent, partition: row.relname, rows: Number(counted[0]?.count ?? 0) });
  }
  return dropped;
}
